import { Pipe, PipeTransform, ChangeDetectorRef, OnDestroy } from '@angular/core';
import { I18nService } from '../services/i18n.service';
import { AsyncPipe } from '@angular/common';
import { Observable } from 'rxjs';

@Pipe({
  name: 'hgShortDate',
  pure: false
})
export class ShortDatePipe implements PipeTransform, OnDestroy {
  async: AsyncPipe;
  previousKey: string;
  previousObservable: Observable<string>;

  constructor(private i18nService: I18nService, private cdRef: ChangeDetectorRef) {
    this.async = new AsyncPipe(this.cdRef);
  }

  transform(key: any): any {
    if (this.previousKey !== key) {
      this.previousKey = key;
      this.previousObservable = this.i18nService.formatShortDate(key);
    }

    return this.async.transform(this.previousObservable);
  }

  ngOnDestroy(): void {
    this.async.ngOnDestroy();
  }
}
