import { Component, ChangeDetectionStrategy, Input, Inject, Injector } from '@angular/core';
import { Scope, scopeToken } from '@honoregaming/core';
import { MessageService } from '../../services/message.service';
import { BetTypeInfosDetailsComponent } from '../bet-type-infos-details/bet-type-infos-details.component';

@Component({
  selector: 'hg-bet-type-infos-icon',
  templateUrl: './bet-type-infos-icon.component.html',
  styleUrls: ['./bet-type-infos-icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetTypeInfosIconComponent {
  @Input() public betTypeId: number = 0;
  @Input() public betTypeContext: string = null;
  @Input() public groupName: string = '';

  constructor(
    private readonly messageService: MessageService,
    private readonly injector: Injector,
    @Inject(scopeToken) private readonly userScope: Scope
  ) {}

  public showDetails(): void {
    this.messageService.sendComponentMessage(BetTypeInfosDetailsComponent, {
      betTypeId: this.betTypeId,
      betTypeContext: this.betTypeContext
    });

    if (this.userScope === Scope.Customer) {
      import('projects/customer/hg-core/src/lib/services/telemetry/telemetry.service').then(({ TelemetryService }) => {
        const telemetryService = this.injector.get(TelemetryService);
        telemetryService.trackEvent('help_indicator_click_bettype', {
          market_id: this.betTypeId,
          market_name: this.groupName
        });
      });
    }
  }
}
