import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  OnInit,
  ChangeDetectorRef
} from '@angular/core';
import { BetTypeService } from '@honoregaming/events';

@Component({
  selector: 'hg-bet-type-infos-details',
  templateUrl: './bet-type-infos-details.component.html',
  styleUrls: ['./bet-type-infos-details.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class BetTypeInfosDetailsComponent implements OnInit {
  @Input()
  public betTypeId: number;

  @Input()
  public betTypeContext?: string;

  @Output()
  public close = new EventEmitter();

  public isLoading: boolean;
  public text: string;

  constructor(private betTypeService: BetTypeService, private cdRef: ChangeDetectorRef) {}

  public ngOnInit(): void {
    this.isLoading = true;

    this.betTypeService.getExplanations(this.betTypeId, this.betTypeContext).subscribe(explanations => {
      this.text = explanations.html;
      this.isLoading = false;
      this.cdRef.markForCheck();
    });
  }
}
